-- ve-explorer-path: the Welcome Guide tour as ~3-second beats (Sean, 2026-11-08): no lip sync, no animation, a new image about every 3 s,
-- a slight slow zoom allowed. Replaces the 24 shots of 20261108_welcome_guide_tour_lookbook.sql. Pictures already made; no new credits.
delete from ve_video_shots where tour_id=(select id from ve_video_tours where slug='welcome-guide');
